<?php $money=static fn(int$v):string=>($v<0?'- ':'').'R$ '.number_format(abs($v)/100,2,',','.');$date=static fn(?string$v):string=>$v?date('d/m/Y',strtotime($v)):'-';$origin=['link'=>'Link de divulgação','codigo'=>'Código informado']; ?>
<header class="panel-page-heading"><div><span>Programa de afiliados</span><h1>Meus indicados</h1><p>Proprietários vinculados ao seu código ou link de divulgação.</p></div></header>
<section class="panel-card admin-filter-card"><form class="affiliate-filter-form" method="get" action="<?= url('/afiliado/indicados') ?>"><label>Nome<input type="search" name="nome" value="<?= e($filters['nome']) ?>"></label><label>E-mail<input type="search" name="email" value="<?= e($filters['email']) ?>"></label><label>Indicado desde<input type="date" name="de" value="<?= e($filters['de']) ?>"></label><label>Indicado até<input type="date" name="ate" value="<?= e($filters['ate']) ?>"></label><div class="form-actions"><button class="btn btn-primary" type="submit">Filtrar</button><a class="btn btn-outline" href="<?= url('/afiliado/indicados') ?>">Limpar</a></div></form></section>
<section class="panel-card"><div class="panel-card-heading"><h2>Proprietários indicados</h2></div><?php if(!$result['items']):?><div class="empty-preview"><span aria-hidden="true">&#9783;</span><div><strong>Nenhuma indicação encontrada</strong><p>Quando seus indicados se cadastrarem, eles aparecerão aqui.</p></div></div><?php else:?><div class="responsive-table"><table class="panel-table affiliate-referred-table"><thead><tr><th scope="col">Proprietário</th><th scope="col">Contato</th><th scope="col">Indicação</th><th scope="col">Origem</th><th scope="col">Chácaras</th><th scope="col">Com mensalidade</th><th scope="col">Comissão</th><th scope="col">Status</th><th scope="col">Ação</th></tr></thead><tbody><?php foreach($result['items']as$item):?><tr><td><strong><?= e($item['nome']) ?></strong></td><td><?= e($item['email']) ?><small><?= e($item['telefone']?:'-') ?></small></td><td><?= e($date($item['afiliado_atribuido_em']?:$item['data_cadastro'])) ?></td><td><?= e($origin[$item['afiliado_origem']]??'Indicação') ?></td><td><?= (int)$item['chacaras'] ?></td><td><?= (int)$item['com_mensalidade'] ?></td><td><strong><?= e($money((int)$item['comissao_centavos'])) ?></strong></td><td><span class="status-pill affiliate-status-<?= e($item['status']) ?>"><?= e(ucfirst($item['status'])) ?></span></td><td><a class="btn btn-outline btn-small" href="<?= url('/afiliado/indicados/'.(int)$item['id']) ?>">Ver chácaras</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php if($result['pages']>1):?><nav class="panel-pagination" aria-label="Paginação"><?php for($p=1;$p<=$result['pages'];$p++):$query=array_merge($filters,['pagina'=>$p]);?><a class="<?= $p===$result['page']?'active':'' ?>" href="<?= url('/afiliado/indicados?'.http_build_query($query)) ?>"><?= $p ?></a><?php endfor;?></nav><?php endif;?></section>
